{
  "predictors": [
    {
      "name": "Revenue Growth Stability",
      "construction": "Calculate the standard deviation of quarterly revenue growth rates over the past 5 years.",
      "rationale": "Firms with stable revenue growth may be better at managing operations and demand, leading to more predictable cash flows.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Employee Productivity",
      "construction": "Compute the ratio of revenue to the number of employees from the most recent annual report.",
      "rationale": "Firms with higher revenue per employee may be using their resources more efficiently, leading to better profitability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Insider Trading Volume",
      "construction": "Aggregate the total volume of shares traded by insiders over the past year, net of purchases and sales.",
      "rationale": "High insider trading volume might indicate management's confidence or concern about future prospects.",
      "higher_returns_for": "high net purchase volumes"
    },
    {
      "name": "Marketing Efficiency",
      "construction": "Calculate the ratio of gross profit to advertising expenses from the last annual report.",
      "rationale": "Firms that convert advertising spend into gross profit more effectively may have superior market strategies.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Deferred Revenue Change",
      "construction": "Measure the change in deferred revenue from the previous to the current fiscal year.",
      "rationale": "An increase in deferred revenue may indicate stronger future sales as it reflects prepaid income for goods/services yet to be delivered.",
      "higher_returns_for": "large positive changes"
    },
    {
      "name": "Patent Portfolio Expansion",
      "construction": "Count the number of new patents granted in the past year.",
      "rationale": "A growing patent portfolio could suggest strong future innovation and competitive advantage.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supplier Concentration",
      "construction": "Calculate the Herfindahl index based on the share of purchases from each supplier reported in the latest 10-K.",
      "rationale": "Lower concentration may reduce supplier risk and dependency, potentially leading to more stable margins.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "CEO Tenure Change",
      "construction": "Identify changes in CEO tenure by comparing CEO names from the current and previous year's annual reports.",
      "rationale": "New executive leadership may bring strategic changes that influence firm performance.",
      "higher_returns_for": "recent CEO changes"
    },
    {
      "name": "Environmental Compliance Costs",
      "construction": "Calculate the cost of environmental compliance divided by total operating costs from the annual report.",
      "rationale": "Lower costs here may indicate operational efficiencies or lower regulatory burden.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Cash Flow Seasonality",
      "construction": "Compute the standard deviation of quarterly operating cash flows over the past 5 years.",
      "rationale": "Low seasonality in cash flows may indicate stable operations, reducing business cycle risk.",
      "higher_returns_for": "low values of the measure"
    }
  ]
}
